const key=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const isImage=value=>/\.(?:avif|jpe?g|png|webp)(?:[?#]|$)/i.test(value||'')||/firebasestorage\.googleapis\.com\/.*(?:alt=media|%2F)/.test(value||'');
function mediaURL(value,{native=false}={}){
 if(typeof value!=='string'||!value.trim())return '';
 const raw=value.trim();
 // The fixed Elios proxy belongs to the atelier, not the Pages origin.
 if(raw.startsWith('/manufacturer-materials/'))return raw;
 if(native&&raw.startsWith('assets/'))return raw;
 try{const url=new URL(raw,'https://leroyfactory.fr/');return url.protocol==='https:'?url.href:'';}catch{return '';}
}
function normalizedEntry(value,fallbackLabel,kind='product',{native=false,color,formats}={}){
 const item=typeof value==='string'?{url:value}:value||{},url=mediaURL(item.fullUrl||item.original||item.hdImage||item.url||item.src||item.image,{native});
 if(!url||/\.pdf(?:#|\?|$)/i.test(url))return null;
 const label=String(item.label||item.alt||item.caption||fallbackLabel||'Vue de la collection');
 const actualKind=['tile','ambience','product'].includes(item.kind)?item.kind:kind;
 const rawFormats=item.formats||formats,formatList=rawFormats?(Array.isArray(rawFormats)?rawFormats:[rawFormats]).map(String):null;
 const preview=mediaURL(item.preview||item.thumbnail,{native});
 return {url,label,kind:actualKind,...(item.color||color?{color:String(item.color||color)}:{}),...(formatList?{formats:formatList}:{}),...(preview&&preview!==url?{preview}:{}),...(native?{native:true}:{}),...(item.definition?{definition:String(item.definition)}:{})};
}
function canonicalRecord(manufacturer,collection){
 const manufacturerKey=key(manufacturer?.name||manufacturer?.id),nameKey=key(collection?.surfaceRecipe?.collection||collection?.name),idKey=key(String(collection?.id||'').replace(/^(?:elios|view)[-_]/i,''));
 return Object.entries(COLLECTIONS).find(([name,record])=>['ELIOS','VIEW'].includes(record.brand)&&manufacturerKey.includes(key(record.brand))&&(key(name)===nameKey||key(name)===idKey))||null;
}
function canonicalGallery(manufacturer,collection){
 const entry=canonicalRecord(manufacturer,collection);if(!entry)return [];
 const [name,record]=entry,selected=collection.selectedColor||collection.surfaceRecipe?.colorId||collection.surfaceRecipe?.color,selectedKey=key(selected);
 const selectedColor=selectedKey?record.colors.find(color=>key(color.id)===selectedKey||key(color.name)===selectedKey):null;
 // A stale/unknown colour must not silently show the first other colour.
 if(selectedKey&&!selectedColor)return [];
 const colors=selectedColor?[selectedColor,...record.colors.filter(color=>color!==selectedColor)]:record.colors,result=[];
 for(const color of colors){
  const formats=formatsForColor(name,color.id).map(format=>format.label||format.id),label=name+' · '+color.name;
  const nativeFaces=color.nativeFaces===true||color.textureProvenance?.manufacturerOriginal===true;
  const original=color.manufacturerSample||(isImage(color.source)?color.source:null);
  // Proven native face variants preserve their reviewed pixels and format.
  // Reconstructed editor variants, notably Yosemite, are never used here.
  if(nativeFaces){
   const originals=color.textureVariants?.max?.length?color.textureVariants.max:color.textureVariants?.balanced?.length?color.textureVariants.balanced:color.faces?.length?color.faces:[color.file];
   for(const [index,file]of originals.entries()){
    if(!file||/reconstruct|generated|synthetic/i.test(file))continue;
    const preview=color.textureVariants?.fluid?.[index]||color.textureVariants?.swatch?.[index];
    const source={url:surfaceAssetURL(file),...(preview&&!/reconstruct|generated|synthetic/i.test(preview)?{preview:surfaceAssetURL(preview)}:{})};
    const value=normalizedEntry(source,label+(originals.length>1?' · Face '+(index+1):''),'tile',{native:true,color:color.name,formats});if(value)result.push(value);
   }
  }
  if(original){const value=normalizedEntry(surfaceAssetURL(original),label,'tile',{native:true,color:color.name,formats});if(value)result.push(value);}
 }
 return result;
}

/** Original collection images for the detail dialog. This is synchronous and
 * performs no request while walking: the dialog alone loads the selected image.
 * Explicit wall/product metadata wins, followed by authentic native faces and
 * exact public full/original selections. Unknown collections retain their own
 * image instead of being assigned another model or colour. */
export function resolveShowroomHDGallery(manufacturer,collection){
 if(!collection||typeof collection!=='object')return [];
 const result=[],seen=new Set(),append=entry=>{if(entry&&!seen.has(entry.url)){seen.add(entry.url);result.push(entry);}};
 const explicit=[...(Array.isArray(collection.gallery)?collection.gallery:[]),...(Array.isArray(collection.hdImages)?collection.hdImages:[])];
 if(collection.hdImage)explicit.unshift({url:collection.hdImage,label:collection.name+(collection.selectedColor?' · '+collection.selectedColor:''),kind:collection.surfaceRecipe?'tile':'product',color:collection.selectedColor});
 for(const value of explicit)append(normalizedEntry(value,collection.name,collection.surfaceRecipe?'tile':'product',{native:!!collection.surfaceRecipe}));
 const publicGallery=PUBLIC_HD_MEDIA[collection.id]||[],selectedKey=key(collection.selectedColor);
 const hasNamedColors=publicGallery.some(item=>key(item.color)),hasSelectedColor=publicGallery.some(item=>key(item.color)===selectedKey);
 const publicOrdered=selectedKey&&hasNamedColors&&!hasSelectedColor?[]:selectedKey?[...publicGallery.filter(item=>key(item.color)===selectedKey),...publicGallery.filter(item=>key(item.color)!==selectedKey)]:publicGallery;
 for(const value of publicOrdered)append(normalizedEntry(value,collection.name,value.kind));
 for(const entry of canonicalGallery(manufacturer,collection))append(entry);
 if(!result.length||!/(?:thumb|preview|covers)/i.test(String(collection.image||'')))append(normalizedEntry(collection.image,collection.name,'ambience')); 
 // Distinct native faces may share their manufacturer's colour label. Keep
 // every source while making its selection chip identifiable to the visitor.
 const totals=new Map(),ranks=new Map();for(const entry of result){const group=key(entry.label);totals.set(group,(totals.get(group)||0)+1);}
 return result.map(entry=>{const group=key(entry.label),total=totals.get(group);if(total<2)return entry;const rank=(ranks.get(group)||0)+1;ranks.set(group,rank);const kind=entry.kind==='tile'?'matière':entry.kind==='ambience'?'ambiance':'visuel';return {...entry,label:entry.label+' · '+kind+' '+rank+' / '+total};});
}
